    const policyHref=document.body.dataset.view==='register'?('course.html?slug='+encodeURIComponent(c.slug)+'&lang='+lang+'#coursePolicies'):'#coursePolicies';
    const r=window.SCOPE?.t?.[lang]?.r||{},fee=money(intl?c.fees?.international:c.fees?.bangladesh),
      steps=interest?[tr('Your details','আপনার তথ্য'),tr('International batch','আন্তর্জাতিক ব্যাচ'),tr('Review','পর্যালোচনা')]:intl?[tr('Your details','আপনার তথ্য'),tr('Payment details','পেমেন্টের তথ্য'),tr('Review','পর্যালোচনা')]:r.steps||[tr('Your details','আপনার তথ্য'),tr('bKash payment','বিকাশ পেমেন্ট'),tr('Review','পর্যালোচনা')],
      next=r.next||tr('Next','পরবর্তী'),back=r.back||tr('Back','পেছনে'),submitLabel=r.go||tr('Submit registration','নিবন্ধন জমা দিন'),
      stepTitle=interest?tr('Register interest','আগ্রহ জানান'):tr('Register for this course','কোর্সে নিবন্ধন করুন'),
      paymentNumber=String(window.SCOPE?.pay?.to||'');
    const field=(name,label,type='text',required=false,attrs='')=>`<label>${esc(label)}${required?'':' <small class="opt">('+esc(tr('optional','ঐচ্ছিক'))+')</small>'}<input name="${name}" type="${type}"${required?' required':''} ${attrs}><small class="er" id="er-${name}"></small></label>`;
    const selectField=(name,label,options)=>'<label>'+esc(label)+' <small class="opt">('+esc(tr('optional','ঐচ্ছিক'))+')</small><select name="'+name+'"><option value="">'+esc(tr('Select','নির্বাচন করুন'))+'</option>'+options.map(x=>'<option value="'+esc(x[0])+'">'+esc(tr(x[0],x[1]))+'</option>').join('')+'</select></label>';
    const nav=(previous,nextStep,last=false)=>`<p class="row">${previous!==null?`<button class="btn ghost-d" type="button" data-go="${previous}">${esc(back)}</button>`:''}${last?`<button class="btn" id="go" type="submit">${esc(submitLabel)}</button>`:`<button class="btn" type="button" data-go="${nextStep}">${esc(next)}</button>`}</p>`;
    const payPanel=interest
